const $=id=>document.getElementById(id);const recipes=[];
function add(id,rows,key,tier=1,out=1,shapeless=false){recipes.push({id,rows,key,tier,out,shapeless});}
add('stick',['P','P'],{P:'oak_planks'},1,4);
add('blaze_powder',['B'],{B:'blaze_rod'},1,2,true);
add('bread',['WWW'],{W:'wheat'},1);
add('white_wool',['SS','SS'],{S:'string'},1);
add('nether_bricks',['NN','NN'],{N:'nether_brick'},1);
for(const [n,m] of [['oak','oak_planks'],['stone','stone'],['light_weighted','gold_ingot'],['heavy_weighted','iron_ingot']])add(n+'_pressure_plate',['MM'],{M:m},1);
for(const [mat,ingredient] of [['stone','cobblestone'],['iron','iron_ingot'],['golden','gold_ingot']]){
for(const [tool,rows] of [['pickaxe',['MMM',' S ',' S ']],['axe',['MM','MS',' S']],['shovel',['M','S','S']],['hoe',['MM',' S',' S']],['sword',['M','M','S']]]){if(mat==='golden'&&!['pickaxe','axe'].includes(tool))continue;add(mat+'_'+tool,rows,{M:ingredient,S:'stick'},tool==='sword'||tool==='shovel'?2:3);}}
add('shears',[' I','I '],{I:'iron_ingot'},2);
add('bucket',['I I',' I '],{I:'iron_ingot'},2);
add('flint_and_steel',['IF'],{I:'iron_ingot',F:'flint'},2,1,true);
add('ender_eye',['PB'],{P:'ender_pearl',B:'blaze_powder'},2,1,true);
for(const mat of ['iron','gold']){add(mat+'_ingot',['NNN','NNN','NNN'],{N:mat+'_nugget'},2);add(mat+'_ingot',['B'],{B:mat+'_block'},2,9,true);}
add('oak_boat',['P P','PPP'],{P:'oak_planks'},3);
add('oak_door',['PP','PP','PP'],{P:'oak_planks'},3,3);
add('iron_door',['II','II','II'],{I:'iron_ingot'},3,3);
add('white_bed',['WWW','PPP'],{W:'white_wool',P:'oak_planks'},3);
add('golden_helmet',['GGG','G G'],{G:'gold_ingot'},3);
add('bow',[' ST','S T',' ST'],{S:'stick',T:'string'},4);
add('respawn_anchor',['OOO','GGG','OOO'],{O:'crying_obsidian',G:'glowstone'},4);
const name=id=>id.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
function normalized(a){let rows=a.map(r=>r.slice());while(rows.length&&rows[0].every(x=>!x))rows.shift();while(rows.length&&rows.at(-1).every(x=>!x))rows.pop();if(!rows.length)return [];while(rows.every(r=>!r[0]))rows.forEach(r=>r.shift());while(rows.every(r=>!r.at(-1)))rows.forEach(r=>r.pop());return rows;}
function pattern(r){return r.rows.map(row=>[...row].map(c=>r.key[c]||null));}
function matches(cells,r){const ids=cells.map(s=>s?.id||null);if(r.shapeless)return JSON.stringify(ids.filter(Boolean).sort())===JSON.stringify(pattern(r).flat().filter(Boolean).sort());const got=JSON.stringify(normalized([ids.slice(0,3),ids.slice(3,6),ids.slice(6,9)]));const p=normalized(pattern(r));return got===JSON.stringify(p)||got===JSON.stringify(p.map(row=>row.slice().reverse()));}
const blocks=new Set(['oak_planks','cobblestone','stone','white_wool','nether_bricks','crying_obsidian','glowstone','iron_block','gold_block','respawn_anchor']);
function visual(id){const plates={oak_pressure_plate:'oak_planks',stone_pressure_plate:'stone',light_weighted_pressure_plate:'gold_block',heavy_weighted_pressure_plate:'iron_block'};if(plates[id])return '<span class="plate">'+visual(plates[id])+'</span>';if(id==='white_bed')return '<span class="bed-model"><span class="bed-top"></span><span class="bed-side"></span><span class="bed-leg"></span></span>';if(blocks.has(id)){const top=id==='respawn_anchor'?'respawn_anchor_top':id;const side=id==='respawn_anchor'?'respawn_anchor_side0':id;return `<span class="cube"><i style="background-image:url(assets/block/${top}.png)"></i><i style="background-image:url(assets/block/${side}.png)"></i><i style="background-image:url(assets/block/${side}.png)"></i></span>`;}return `<img src="assets/item/${id}.png" alt="${name(id)}" draggable="false">`;}
let grid=Array(9).fill(null),inv=Array(27).fill(null),held=null,score=0,count=0,seconds=90,limit=90,active=true,current,hinted=false,last='',best=0;
try{best=Number(localStorage.getItem('crafting-trials-best'))||0;}catch{}$('best').textContent=best;
function saveBest(){if(score>best){best=score;$('best').textContent=best;try{localStorage.setItem('crafting-trials-best',best);}catch{}}}
function updateCursor(){const el=$('cursor');el.hidden=!held;if(held)el.innerHTML=visual(held.id)+`<span class="qty">${held.n}</span>`;}
function slot(el,s){el.innerHTML=s?visual(s.id)+(s.n>1?`<span class="qty">${s.n}</span>`:''):'';el.title=s?`${name(s.id)} × ${s.n}`:'Empty slot';el.setAttribute('aria-label',el.title);}
function render(){[...$('grid').children].forEach((el,i)=>slot(el,grid[i]));[...$('inventory').children].forEach((el,i)=>slot(el,inv[i]));let valid=matches(grid,current);$('output').disabled=!valid||!active;slot($('output'),valid?{id:current.id,n:current.out}:null);$('score').textContent=String(score).padStart(4,'0');$('count').textContent=count;$('level').textContent=['Apprentice','Artisan','Expert','Master'][Math.min(3,Math.floor(count/4))];updateCursor();}
function next(){grid.fill(null);held=null;hinted=false;$('hintGrid').hidden=true;$('hint').disabled=false;const tier=Math.min(4,1+Math.floor(count/3));const pool=recipes.filter(r=>r.tier<=tier&&r.id!==last);current=pool[Math.floor(Math.random()*pool.length)];last=current.id;const needed=[...new Set(Object.values(current.key))];const extras=['oak_planks','stick','cobblestone','iron_ingot','gold_ingot','string','flint','wheat','stone','blaze_powder','nether_brick','white_wool'].filter(x=>!needed.includes(x)).sort(()=>Math.random()-.5).slice(0,Math.min(12,3+count));const ids=[...needed,...extras].sort(()=>Math.random()-.5);inv=Array(27).fill(null);ids.forEach((id,i)=>inv[i]={id,n:16});limit=Math.max(25,90-count*3);seconds=limit;$('target').textContent=name(current.id);$('targetIcon').innerHTML=visual(current.id);$('round').textContent=String(count+1).padStart(2,'0');$('reward').textContent=`+${100+count*20} points`;$('description').textContent=current.shapeless?'A shapeless recipe. Ingredients can go anywhere.':'Arrange the ingredients in the crafting grid, then collect the result.';$('feedback').textContent='Place ingredients to match the recipe.';render();tickDisplay();}
function tickDisplay(){$('time').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;$('bar').style.width=100*seconds/limit+'%';$('bar').style.background=seconds<15?'#e6a26d':'var(--green)';}
function collect(){if(!active||!matches(grid,current))return;const gain=100+count*20;score+=gain;count++;saveBest();next();$('feedback').textContent=`✓ Crafted! +${gain} points`;}
$('output').onclick=collect;
function stash(s){if(!s)return;for(const a of inv){if(a&&a.id===s.id&&a.n<64){let n=Math.min(64-a.n,s.n);a.n+=n;s.n-=n;if(!s.n)return;}}let i=inv.findIndex(x=>!x);if(i>=0)inv[i]={...s};}
$('clear').onclick=()=>{if(!active)return;grid.forEach(s=>stash(s));grid.fill(null);stash(held);held=null;render();};
let gesture=null;
function cellAt(x,y){const el=document.elementFromPoint(x,y)?.closest('[data-zone]');return el?{arr:el.dataset.zone==='grid'?grid:inv,index:+el.dataset.index,el}:null;}
function interact(c,right){const s=c.arr[c.index];if(!held){if(s){let n=right?Math.ceil(s.n/2):s.n;held={id:s.id,n};s.n-=n;if(!s.n)c.arr[c.index]=null;}}else if(!s||s.id===held.id){const n=Math.min(right?1:held.n,64-(s?.n||0));if(n){if(!s)c.arr[c.index]={id:held.id,n:0};c.arr[c.index].n+=n;held.n-=n;if(!held.n)held=null;}}else if(!right){c.arr[c.index]=held;held=s;}render();}
function onDown(e){if(!active||![0,2].includes(e.button))return;e.preventDefault();const c=cellAt(e.clientX,e.clientY);if(!c)return;const hadHeld=!!held;gesture={start:c,hadHeld,right:e.button===2,moved:false,targets:[],x:e.clientX,y:e.clientY};if(!hadHeld)interact(c,e.button===2);else gesture.targets=[c];moveCursor(e);}
function moveCursor(e){$('cursor').style.left=e.clientX+12+'px';$('cursor').style.top=e.clientY+12+'px';}
document.addEventListener('pointermove',e=>{moveCursor(e);if(!gesture)return;if(Math.hypot(e.clientX-gesture.x,e.clientY-gesture.y)>5)gesture.moved=true;const c=cellAt(e.clientX,e.clientY);if(!c||!held)return;if(gesture.hadHeld){if((!c.arr[c.index]||c.arr[c.index].id===held.id)&&!gesture.targets.some(t=>t.arr===c.arr&&t.index===c.index)){gesture.targets.push(c);c.el.classList.add('selected');}}});
document.addEventListener('pointerup',e=>{if(!gesture)return;const g=gesture;gesture=null;document.querySelectorAll('.selected').forEach(e=>e.classList.remove('selected'));if(!held)return;if(g.hadHeld){if(!g.moved)interact(g.start,g.right);else{const targets=g.targets.filter(c=>!c.arr[c.index]||c.arr[c.index].id===held.id);const per=g.right?1:Math.floor(held.n/Math.max(1,targets.length));for(const c of targets){if(!held)break;const n=Math.min(per,held.n,64-(c.arr[c.index]?.n||0));if(n>0){if(!c.arr[c.index])c.arr[c.index]={id:held.id,n:0};c.arr[c.index].n+=n;held.n-=n;if(!held.n)held=null;}}}}else if(g.moved){const c=cellAt(e.clientX,e.clientY);if(c&&(c.arr!==g.start.arr||c.index!==g.start.index))interact(c,g.right);}render();});
for(const zone of ['grid','inventory'])for(let i=0;i<(zone==='grid'?9:27);i++){let b=document.createElement('button');b.className='slot';b.dataset.zone=zone;b.dataset.index=i;b.onpointerdown=onDown;b.oncontextmenu=e=>e.preventDefault();b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();interact({arr:zone==='grid'?grid:inv,index:i},e.shiftKey);}};$(zone).append(b);}
$('hint').onclick=()=>{if(!active||hinted)return;hinted=true;score=Math.max(0,score-25);$('hint').disabled=true;let p=pattern(current);$('hintGrid').innerHTML=Array.from({length:9},(_,i)=>{let id=p[Math.floor(i/3)]?.[i%3];return id?`<span title="${name(id)}">${visual(id)}</span>`:'<span></span>';}).join('');$('hintGrid').hidden=false;render();};
function modal(html){$('modalContent').innerHTML=html;$('modal').showModal();}
$('close').onclick=()=>$('modal').close();$('help').onclick=()=>modal('<div class="eyebrow">THE CRAFTER’S HANDBOOK</div><h2>Build. Remember. Repeat.</h2><p>Craft the requested item before time runs out. Click the output to earn points. Every three crafts unlock harder recipes; every craft shortens your next timer.</p><p><b>Left-click</b> picks up or places a stack. <b>Right-click</b> picks up half a stack or places one item. With a stack held, <b>left-drag</b> across slots to divide it evenly; <b>right-drag</b> places one per slot. Dragging directly from inventory moves a stack.</p><p><b>Keyboard:</b> Tab to a slot and press Enter to pick up/place; Shift+Enter splits/places one. On touch, tap to pick up and place.</p><p>Recipes work in every valid grid position, including mirrored shapes. Shapeless ingredients work anywhere. One item is consumed per occupied recipe slot.</p><p>Ingots use nuggets or metal blocks; nether bricks use four nether brick items. These are crafting recipes, so no furnace is needed. Wood variants use oak; wool and beds use white.</p><p>Revealing a recipe costs 25 points (minimum score 0). Your personal best is saved in this browser. The clock pauses while this window is open.</p><p><a href="https://minecraft.wiki/w/Crafting" target="_blank" rel="noreferrer">Vanilla recipe reference ↗</a></p>');
function restart(){active=true;score=0;count=0;last='';if($('modal').open)$('modal').close();next();}
$('restart').onclick=restart;setInterval(()=>{if(!active||$('modal').open)return;seconds=Math.max(0,seconds-1);tickDisplay();if(!seconds){active=false;stash(held);held=null;render();modal(`<div class="eyebrow">RUN COMPLETE</div><h2>Time to refuel.</h2><p>You crafted ${count} items and scored <b>${score}</b> points.</p><p>Personal best: <b>${best}</b></p><button class="primary" id="again">Try again →</button>`);$('again').onclick=restart;}},1000);next();
if(typeof module!=='undefined')module.exports={normalized,matches,recipes,pattern};
